def difference(d1, d2, level=-1):
    """
    Returns a dictionary with items from d1 not contained in d2.
    The maximum depth of recursion can be set with the level parameter.
    For infinite recursion, set level to -1.
    For level 1, if a key is present both in d1 and d2 but has different values,
    it is included into the difference.
    See intersection() for more details.
    d1 and d2 remain unchanged. However, d1 or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    # Make a copy of d1 to modify and return
    result = d1.copy()
    # Recursively compare dictionaries
    if level == -1:
        return _deep_difference(result, d2)
    else:
        return _difference(result, d2, 0, level)

def _difference(d1, d2, current_level, max_level):
    # Check if we have reached the maximum recursion level
    if current_level == max_level:
        return d1
    # Compare the keys of the two dictionaries
    for key in d1.keys():
        # If the key is not in d2, include it in the difference
        if key not in d2:
            continue
        # If the values are not the same, include the key in the difference
        if d1[key] != d2[key]:
            continue
        # If the values are the same, recursively compare the subdictionaries
        if isinstance(d1[key], dict) and isinstance(d2[key], dict):
            _difference(d1[key], d2[key], current_level+1, max_level)
    return d1

def _deep_difference(d1, d2):
    # Recursively compare the dictionaries without a maximum recursion level
    for key in d1.keys():
        # If the key is not in d2, include it in the difference
        if key not in d2:
            continue
        # If the values are not the same, include the key in the difference
        if d1[key] != d2[key]:
            continue
        # If the values are the same, recursively compare the subdictionaries
        if isinstance(d1[key], dict) and isinstance(d2[key], dict):
            _deep_difference(d1[key], d2[key])
    return d1
