def _eval_file(prefix, file_path):
    file_name = file_path.split("/")[-1]
    file_extension = file_name.split(".")[-1]
    if file_extension == "xml":
        with open(file_path, "r") as f:
            xml_data = f.read()
            root = ET.fromstring(xml_data)
            for child in root:
                if child.tag == "artery":
                    package_name = child.attrib["name"]
                    package_type = child.attrib["type"]
                    if package_type == "asset":
                        assets_dict[package_name] = file_path
                    elif package_type == "rendition":
                        renditions_dict[package_name] = file_path
                    else:
                        raise ValueError("Invalid package type")
    return assets_dict, renditions_dict
