def _explore_zipfile(zip_path: str) -> dict:
    with zipfile.ZipFile(zip_path, 'r') as zip_file:
        data = {}
        for file in zip_file.filelist:
            if file.filename.endswith('.xml'):
                xml_basename = os.path.splitext(os.path.basename(file.filename))[0]
                data[xml_basename] = _unzip_package_data(zip_file, file)
        return data

def _unzip_package_data(zip_file, file) -> dict:
    with zip_file.open(file) as xml_file:
        tree = xml.etree.ElementTree.parse(xml_file)
        root = tree.getroot()
        return {
            'element1': root.find('.//element1').text.strip(),
            'element2': root.find('.//element2').text.strip(),
            'element3': root.find('.//element3').text.strip()
        }

