def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0
    for dirpath, _, filenames in os.walk(self.root):
        for filename in filenames:
            if filename.endswith(".json"):
                filepath = os.path.join(dirpath, filename)
                with open(filepath, "r", encoding="utf-8") as f:
                    try:
                        data = json.load(f)
                    except json.JSONDecodeError:
                        if show_warnings:
                            print(f"Warning: Could not parse {filepath} as JSON")
                        continue
                    num_objects += 1
                    if validate_objects:
                        if not data["type"] in self.allowed_types:
                            if show_warnings:
                                print(f"Warning: {filepath} has an invalid type: {data['type']}")
                            continue
                        if check_digests:
                            digest = self.calculate_digest(data)
                            if digest != data["digest"]:
                                if show_warnings:
                                    print(f"Warning: {filepath} has an invalid digest")
                                continue
                    good_objects += 1
    return num_objects, good_objects
