def deep_merge_nodes(nodes):
    """
    Deep merge nodes with same keys.

    Args:
        nodes (list): List of tuples containing ScalarNodes and MappingNodes.

    Returns:
        list: List of merged tuples.
    """
    merged_nodes = []
    for node in nodes:
        if node not in merged_nodes:
            merged_nodes.append(node)
        else:
            for i, existing_node in enumerate(merged_nodes):
                if existing_node[0] == node[0]:
                    if isinstance(existing_node[1], MappingNode) and isinstance(node[1], MappingNode):
                        merged_nodes[i] = (existing_node[0], deep_merge_nodes([existing_node[1], node[1]]))
                    else:
                        merged_nodes[i] = node
                    break
    return merged_nodes
