def windows_split(s):
    """Split command-line string, according to Windows rules"""
    result = []
    curr = ''
    bs_count = 0
    in_quotes = False
    for c in s:
        if c == '\\':
            bs_count += 1
            continue
        if c == '"':
            if bs_count % 2 == 0:
                in_quotes = not in_quotes
        else:
            if not in_quotes and c in ' \t\r\n':
                result.append(curr)
                curr = ''
                bs_count = 0
                continue
        bs_count = 0
        curr += c
    if in_quotes or bs_count % 2 == 1:
        raise ValueError("Invalid command-line string: %r" % s)
    result.append(curr)
    return result
