def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """

    def _verify_candidate(iface, candidate):
        if iface.providedBy(candidate):
            return True
        return False

    def _verify_attributes(iface, candidate):
        for name, attr in iface.getLocals().items():
            if not hasattr(candidate, name):
                return False
            if not _verify_attribute(attr, candidate):
                return False
        return True

    def _verify_methods(iface, candidate):
        for name, method in iface.getMethods().items():
            if not hasattr(candidate, name):
                return False
            if not _verify_method(method, candidate):
                return False
        return True

    def _verify_method(method, candidate):
        return _verify_attribute(method, candidate)

    def _verify_attribute(attr, candidate):
        attr_value = getattr(candidate, attr.getName())
        if not callable(attr_value):
            return True
        attr_signature = inspect.signature(attr_value)
        return attr_signature == attr.getSignature()

    def _raise_error(iface, candidate, tentative=False):
        errors = []
        if not _verify_candidate(iface, candidate):
            errors.append(f"{candidate} does not provide {iface}")
        if not _verify_attributes(iface, candidate):
            errors.append(f"{candidate} does not define all required attributes")
        if not _verify_methods(iface, candidate):
            errors.append(f"{candidate} does not define all required methods")
        if tentative:
            return None
        raise zope.interface.Invalid(errors)

    if tentative:
        return _verify_candidate(iface, candidate)
    else:
        errors = _raise_error(iface, candidate)
        if errors:
            raise zope.interface.Invalid(errors)
        return True
