    # Check if the candidate claims that it provides the interface
    if not tentative and not iface.providedBy(candidate):
        raise Invalid(f"{candidate!r} does not provide {iface!r}")

    # Check that the candidate defines all the necessary methods
    for name, method in iface.namesAndDescriptions(lambda d: d.queryTaggedValue("method")):
        if not hasattr(candidate, name):
            raise Invalid(f"{candidate!r} does not define method {name!r}")
        # Check the method signature (to the extent possible)
