def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        # Try parsing as JSON
        data = json.loads(document)
        return {
            'subject': data['subject'],
            'links': [link['href'] for link in data['links']],
            'properties': {prop['rel']: prop['value'] for prop in data['properties']}
        }
    except json.JSONDecodeError:
        # Try parsing as XRD
        root = xml.etree.ElementTree.fromstring(document)
        data = {}
        for child in root:
            if child.tag == '{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject':
                data['subject'] = child.text
            elif child.tag == '{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link':
                data['links'] = [link.attrib['href'] for link in child]
            elif child.tag == '{http://docs.oasis-open.org/ns/xri/xrd-1.0}Property':
                data['properties'] = {prop.attrib['name']: prop.attrib['value'] for prop in child}
        return data
