def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    from lxml import etree

    try:
        response = requests.get(f"https://{handle}/.well-known/webfinger")
        response.raise_for_status()
        xml = etree.fromstring(response.content)
        return {
            "subject": xml.findtext(".//{http://www.w3.org/2005/Atom}subject"),
            "aliases": [
                alias.text
                for alias in xml.findall(".//{http://www.w3.org/2005/Atom}aliases/{http://www.w3.org/2005/Atom}alias")
            ],
            "links": [
                {
                    "rel": link.get("rel"),
                    "type": link.get("type"),
                    "href": link.get("href"),
                }
                for link in xml.findall(".//{http://www.w3.org/2005/Atom}links/{http://www.w3.org/2005/Atom}link")
